import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSpaceAction } from "../handlers/updateSpaceAction";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateSpaceActionRequest } from "../types/UpdateSpaceActionRequest";

type Data = Awaited<ReturnType<typeof updateSpaceAction>>;
type Vars = { spaceId: SpacePartition; actionId: string; req: UpdateSpaceActionRequest };

export function useUpdateSpaceAction(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSpaceAction(vars.spaceId, vars.actionId, vars.req),
    ...options,
  });
}
